-- Bundles the modules into dist/rotorheads.lua, the single file loaded by the mission.
-- Usage (from the mission/ folder): lua5.1 tools/build.lua

local MODULES = {
  "util", "config", "core", "dcs",
  "logistics", "outposts", "factories", "redair", "lives",
  "markers", "convoy", "livemap", "ctld", "csar", "main",
}

local function read(path)
  local f = assert(io.open(path, "r"), "cannot open " .. path)
  local s = f:read("*a")
  f:close()
  return s
end

local parts = {
  "-- Rotorheads-style helicopter campaign for DCS World. Generated by tools/build.lua; edit src/rh/*.lua instead.",
  "-- Requires MOOSE to be loaded first and io/lfs/os de-sanitized in Scripts/MissionScripting.lua.",
  "",
}
for _, name in ipairs(MODULES) do
  local src = read("src/rh/" .. name .. ".lua")
  local chunk, err = loadstring(src, name)
  if not chunk then error("syntax error in " .. name .. ": " .. err) end
  table.insert(parts, "-- ===== " .. name .. ".lua =====")
  table.insert(parts, "do")
  table.insert(parts, src)
  table.insert(parts, "end")
end
table.insert(parts, "")
table.insert(parts, "RH.start()")

os.execute("mkdir -p dist 2>/dev/null || mkdir dist")
local out = assert(io.open("dist/rotorheads.lua", "w"))
out:write(table.concat(parts, "\n"), "\n")
out:close()

assert(loadstring(read("dist/rotorheads.lua"), "rotorheads"), "bundle failed to compile")
print("wrote dist/rotorheads.lua (" .. #MODULES .. " modules)")
